contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);
        uint callerBefore = address(this).balance;
        c.sudicideAnyone(); if (__ESBMC_reverted()) return;
        uint midBalanceC = address(c).balance;
        uint midBalanceCaller = address(this).balance;
        c.sudicideAnyone(); if (__ESBMC_reverted()) return;
        assert(
            midBalanceC == 0 &&
            address(c).balance == 0 &&
            midBalanceCaller >= callerBefore &&
            address(this).balance >= midBalanceCaller &&
            dummy >= 0
        );
    }
    receive() external payable {}
}

