// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(uint256 dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        uint callerBefore = address(this).balance;
        try c.sudicideAnyone() {} catch { return; }
        uint midBalanceC = address(c).balance;
        uint midBalanceCaller = address(this).balance;
        try c.sudicideAnyone() {} catch { return; }
        assertTrue(midBalanceC == 0 &&
            address(c).balance == 0 &&
            midBalanceCaller >= callerBefore &&
            address(this).balance >= midBalanceCaller &&
            dummy >= 0);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
